public class ReliabilityStoreTest {
 static int n;static void ok(boolean v){n++;if(!v)throw new AssertionError("reliability "+n);}interface Attempt{void run()throws Exception;}static void rejects(Attempt a)throws Exception{try{a.run();throw new AssertionError("expected rejection "+n);}catch(IOException|IllegalArgumentException expected){n++;}}
 static String id(){return java.util.UUID.randomUUID().toString();}static JSONObject change(String id,int revision,String action)throws Exception{return new JSONObject().put("id",id).put("revision",revision).put("action",action).put("changeId",id());}
 static class FakeConnection extends HttpURLConnection {boolean disconnected;FakeConnection()throws Exception{super(new URL("https://fixture.invalid/"));}public void disconnect(){disconnected=true;}public boolean usingProxy(){return false;}public void connect(){throw new AssertionError("No real network allowed");}}
 public static void main(String[] args)throws Exception{Path temp=Files.createTempDirectory("loki-reliability-");MainActivity c=new MainActivity(temp.toFile());try{
 rejects(()->ReviewStore.read(c,"../escape"));ReviewStore.write(c,"bound",new JSONObject().put("value","before"));rejects(()->ReviewStore.write(c,"bound",new JSONObject().put("value","x".repeat(1500001))));ok(ReviewStore.read(c,"bound").getString("value").equals("before"));
 String note=id();PersonalNotes.save(c,new JSONObject().put("id",note).put("kind","memo").put("text","one"));JSONObject edit=change(note,1,"edit").put("text","two");ok(PersonalNotes.change(c,edit).getInt("revision")==2);ok(PersonalNotes.change(c,edit).getInt("revision")==2);ok(PersonalNotes.detail(c,note).getJSONArray("history").getJSONObject(0).getString("text").equals("one"));rejects(()->PersonalNotes.change(c,new JSONObject(edit.toString()).put("text","different")));rejects(()->PersonalNotes.change(c,change(note,1,"edit").put("text","stale")));PersonalNotes.change(c,change(note,2,"undo").put("index",0));ok(PersonalNotes.detail(c,note).getString("text").equals("one"));PersonalNotes.delete(c,note);ok(PersonalNotes.list(c).length()==0);ok(PersonalNotes.trash(c).length()==1);rejects(()->PersonalNotes.save(c,new JSONObject().put("id",note).put("kind","memo").put("text","one")));ok(PersonalNotes.detail(c,note).optLong("deletedAt")>0);PersonalNotes.change(c,change(note,4,"restore"));ok(PersonalNotes.list(c).length()==1);rejects(()->PersonalNotes.change(c,change(note,5,"purge")));for(int i=0;i<12;i++){JSONObject row=PersonalNotes.detail(c,note);PersonalNotes.change(c,change(note,row.getInt("revision"),"edit").put("text","version "+i));}ok(PersonalNotes.detail(c,note).getJSONArray("history").length()==10);PersonalNotes.delete(c,note);int rev=PersonalNotes.detail(c,note).getInt("revision");PersonalNotes.change(c,change(note,rev,"purge"));rejects(()->PersonalNotes.detail(c,note));
 JSONObject card=SecretaryInbox.save(c,"old request","synthetic",id()).getJSONObject("item");String cardId=card.getString("id");SecretaryInbox.action(c,new JSONObject().put("id",cardId).put("revision",1).put("action","edit-fields").put("title","new title").put("request","new request"));JSONObject updated=SecretaryInbox.get(c,cardId).getJSONObject("item");ok(updated.getInt("revision")==2);ok(updated.getJSONArray("history").getJSONObject(0).getString("request").equals("old request"));SecretaryInbox.action(c,new JSONObject().put("id",cardId).put("revision",2).put("action","undo-edit").put("index",0));ok(SecretaryInbox.get(c,cardId).getJSONObject("item").getString("request").equals("old request"));SecretaryInbox.action(c,new JSONObject().put("id",cardId).put("revision",3).put("action","delete"));ok(SecretaryInbox.list(c).getJSONArray("items").length()==0);ok(SecretaryInbox.trash(c).length()==1);rejects(()->SecretaryInbox.get(c,cardId));SecretaryInbox.action(c,new JSONObject().put("id",cardId).put("revision",4).put("action","restore"));ok(SecretaryInbox.get(c,cardId).getJSONObject("item").getInt("revision")==5);ok(CalendarWriter.writes==0);
 String before=id();CancellableWork.reserve(c,"image",before);CancellableWork.cancel(c,"image",before);rejects(()->CancellableWork.enter(c,"image",before));CancellableWork.finish(false);ok(!CancellableWork.list(c).getJSONObject(0).optBoolean("canStop"));ok(CancellableWork.list(c).getJSONObject(0).getString("phase").equals("STOPPED"));ok(CancellableWork.wasStopped(c,"image",before));rejects(()->CancellableWork.enter(c,"image",before));String sent=id();CancellableWork.reserve(c,"image",sent);CancellableWork.enter(c,"image",sent);FakeConnection connection=new FakeConnection();CancellableWork.bind(connection);CancellableWork.sending(42);JSONObject stopped=CancellableWork.cancel(c,"image",sent);ok(stopped.optInt("sentRequests")==1);ok(stopped.optLong("sentBytes")==42);ok(connection.disconnected);rejects(()->CancellableWork.sending(100));CancellableWork.finish(true);ok(CancellableWork.list(c).getJSONObject(0).getString("phase").equals("COMPLETED_AFTER_STOP"));rejects(()->CancellableWork.cancel(c,"image",sent));String a=id(),b=id();CancellableWork.reserve(c,"image",a);CancellableWork.reserve(c,"video",b);CancellableWork.enter(c,"image",a);CancellableWork.cancel(c,"video",b);CancellableWork.check();ok(true);CancellableWork.finish(true);rejects(()->CancellableWork.enter(c,"video",b));CancellableWork.finish(false);
 String meeting="1760000000000-"+id();File folder=MeetingAudioStore.folder(c,meeting);JSONArray parts=new JSONArray();for(int i=0;i<7;i++)parts.put(new JSONObject().put("bytes",i==6?160000:320000).put("sha","a".repeat(64)));JSONObject meta=new JSONObject().put("id",meeting).put("parts",parts).put("pcmBytes",2080000);Files.writeString(new File(folder,"session.json").toPath(),meta.toString());Files.write(new File(folder,"transcript-0000.gcm").toPath(),DeviceSecrets.photos().encrypt("first minute".getBytes("UTF-8")));JSONArray timeline=TranscriptTimeline.read(c,meeting);ok(timeline.length()==1);ok(timeline.getJSONObject(0).getLong("startMs")==0);ok(timeline.getJSONObject(0).getLong("endMs")==60000);JSONObject preview=MeetingConsent.preview(c,meeting);ok(preview.getLong("audioBytes")==160000);ok(preview.getInt("maximumRequests")==2);MeetingConsent.consume(c,meeting,preview.getString("token"));rejects(()->MeetingConsent.consume(c,meeting,preview.getString("token")));JSONObject changed=MeetingConsent.preview(c,meeting);Files.write(new File(folder,"transcript-0006.gcm").toPath(),DeviceSecrets.photos().encrypt("last five seconds".getBytes("UTF-8")));rejects(()->MeetingConsent.consume(c,meeting,changed.getString("token")));JSONArray second=TranscriptTimeline.read(c,meeting);ok(second.length()==2);ok(second.getJSONObject(1).getLong("startMs")==60000);ok(second.getJSONObject(1).getLong("endMs")==65000);ok(second.getJSONObject(1).getBoolean("approximate"));ok(!Files.readString(new File(c.getFilesDir(),"reliability-jobs.gcm").toPath(),java.nio.charset.StandardCharsets.ISO_8859_1).contains("sentBytes"));
 System.out.println("PASS reliability history/trash/cancellation/consent/timeline "+n+"; no network or calendar calls");
 }finally{try(java.util.stream.Stream<Path> paths=Files.walk(temp)){for(Path p:paths.sorted(java.util.Comparator.reverseOrder()).toList())Files.delete(p);}}
 }
}
